import type * as Channel3Api from "../../../../index.js";
/**
 * @example
 *     {}
 */
export interface CreateCollectionRequest {
    /** Display name. Defaults to 'Collection {n}' for this account or user. */
    name?: string | null;
    /** Optional vendor-facing notes for this collection. */
    description?: string | null;
    /** Optional partner user id. Scopes the collection to one end user and serves as the default x-user-id on collection-scoped search, browse, and conversation requests when the caller omits that header. */
    user_id?: string | null;
    /** OR across clauses. Within a clause, brand_ids, website_ids, and category_ids are ORed inside each list and ANDed across lists. Empty is allowed so a collection can be created before any items are added. */
    clauses?: Channel3Api.CollectionClauseInput[];
}
